$db=db();$lesson=query_one("SELECT l.id FROM lessons l JOIN grades g ON g.id=l.grade_id JOIN subjects s ON s.id=l.subject_id WHERE g.grade_number=10 AND s.name_en='Buddhism' AND l.medium='Sinhala' AND l.display_order=3 AND l.title_si='තෙරුවන ගුණ හැඳින ගනිමු' AND l.status='active' LIMIT 1");if(!$lesson)throw new RuntimeException('Grade 10 Sinhala Buddhism lesson 3 was not found.');
